int32_t Memory_compare_bytes(Memory* self, int64_t first, int64_t second, int64_t bytes) { (void)self; return bytes > 0 ? (int32_t)memcmp((const void*)(intptr_t)first, (const void*)(intptr_t)second, (size_t)bytes) : 0; }
